contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(
        uint64 n,
        uint64 t,
        uint256 b,
        bytes32 h,
        uint64 s,
        bytes32 bh,
        uint256 o,
        uint256 sc
    ) public {
        bool reverted;
        c.setL1BlockValues(n, t, b, h, s, bh, o, sc); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            reverted &&
            c.number() == 0 &&
            c.timestamp() == 0 &&
            c.basefee() == 0 &&
            c.hash() == bytes32(0) &&
            c.sequenceNumber() == 0 &&
            c.batcherHash() == bytes32(0) &&
            c.l1FeeOverhead() == 0 &&
            c.l1FeeScalar() == 0
        );
    }
    receive() external payable {}
}

