// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 t, uint256 b, bytes32 h, uint64 s, bytes32 bh, uint256 o, uint256 sc) internal {
        bool reverted;
        try c.setL1BlockValues(n, t, b, h, s, bh, o, sc) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted &&
            c.number() == 0 &&
            c.timestamp() == 0 &&
            c.basefee() == 0 &&
            c.hash() == bytes32(0) &&
            c.sequenceNumber() == 0 &&
            c.batcherHash() == bytes32(0) &&
            c.l1FeeOverhead() == 0 &&
            c.l1FeeScalar() == 0);
    }

    function testFuzz_run(uint64 n, uint64 t, uint256 b, bytes32 h, uint64 s, bytes32 bh, uint256 o, uint256 sc) public {
        _run(n, t, b, h, s, bh, o, sc);
    }

    receive() external payable {}
}
